  function BetterQoL.combo_partners.list_show(screen, show, list, first, sel, cur)
    if screen.backdrop then
      funcLuaMenuCommand(711242136, BetterQoL.combo_partners.BG, 0, show)
      if show then
        VRFW.host.menu_command(558735651, BetterQoL.combo_partners.BG, 2311471971, 515167937, 3512665951, 0, 0)
      end
    end
    BetterQoL.combo_partners.open_layer(BetterQoL.combo_partners.LIST)
    funcLuaMenuCommand(711242136, BetterQoL.combo_partners.LIST, 0, show)
    VRFW.host.menu_command(3405944500, BetterQoL.combo_partners.LIST, BetterQoL.combo_partners.TITLE, false, 0)
    -- A row is drawn again only when it shows another entry or its pick state changed.
    for k = 0, BetterQoL.combo_partners.VIEW - 1 do
      local e = show and list[first + k + 1] or nil
      BetterQoL.combo_partners.open_layer(BetterQoL.combo_partners.ITEM, k)
      local was = BetterQoL.combo_partners.ROWS[k]
      if e ~= nil then
        local focused, current = first + k == sel, e.hdl == cur
        if was ~= nil and was.e == e and was.taken == e.taken and was.current == current then
          if was.focused ~= focused then
            pcall(BetterQoL.combo_partners.focus, k, focused)
            was.focused = focused
          end
        else
          local ok = pcall(BetterQoL.combo_partners.row, k, e, focused, current)
          BetterQoL.combo_partners.ROWS[k] = ok and {e = e, taken = e.taken, current = current, focused = focused} or nil
        end
      else
        BetterQoL.combo_partners.ROWS[k] = nil
        if not show then
          BetterQoL.combo_partners.face_forget(BetterQoL.combo_partners.ITEM, k)
        end
      end
      if was == nil or e == nil then
        funcLuaMenuCommand(711242136, BetterQoL.combo_partners.ITEM, k, e ~= nil)
      end
    end
  end

