  -- the screen's squad (screen.members), field order
  function BetterQoL.combo_partners.candidates(screen, info)
    local members = screen.members()
    if members == nil then
      return nil
    end
    local out, seen = {}, {}
    local formation = members.formation
    for _, m in ipairs(members) do
      local h = BetterQoL.combo_partners.U32(m.hdl)
      if h ~= 0 and h ~= screen.player and not seen[h] and #out < BetterQoL.combo_partners.MAX_TEAM and not BetterQoL.combo_partners.is_staff(h) then
        seen[h] = true
        local e = BetterQoL.combo_partners.entry(h)
        e.idx, e.field, e.x = m.index or #out, false, 0
        local slot = m.slot
        if type(slot) == "number" and slot >= 0 and slot <= 10 and type(formation) == "number" then
          local gf, icon = VRFW.host.command(BetterQoL.combo_partners.FORMATION_INFO, 5, formation, slot)
          if gf and type(icon) == "number" and icon >= 0 and icon <= 3 then
            local gq, x = VRFW.host.command(BetterQoL.combo_partners.FORMATION_INFO, 4, formation, slot, 2)
            e.pos, e.field = icon, true
            e.x = (gq and type(x) == "number") and x or slot
          end
        end
        out[#out + 1] = e
      end
    end
    table.sort(out, function(a, b)
      if a.field ~= b.field then
        return a.field
      end
      local pa, pb = a.pos or 9, b.pos or 9
      if pa ~= pb then
        return pa < pb
      end
      if a.field and a.x ~= b.x then
        return a.x < b.x
      end
      return a.idx < b.idx
    end)
    table.insert(out, 1, {hdl = 0, chara = 0, name = BetterQoL.combo_partners.text(BetterQoL.combo_partners.TX_RANDOM)})
    return out
  end

  function BetterQoL.combo_partners.get(h, skill)
    local r = {VRFW.host.command(BetterQoL.combo_partners.CMD_GET, h, skill)}
    local out = {}
    if r[1] == true then
      for k = 2, 4 do
        out[#out + 1] = type(r[k]) == "number" and BetterQoL.combo_partners.U32(r[k]) or 0
      end
    end
    return out
  end

