  -- the squad handle of slot k's named partner (the engine's own pick for that slot), 0 = none or not in the squad
  function BetterQoL.combo_partners.named_default(list, info, k)
    local c = info.named[k]
    if c ~= nil then
      for _, e in ipairs(list) do
        if e.hdl ~= 0 and e.chara == c then
          return e.hdl
        end
      end
    end
    return 0
  end

  -- Returns the performers in cast order.
  function BetterQoL.combo_partners.performers(player, list, picks, info)
    local function entry(h)
      for _, e in ipairs(list) do
        if h ~= 0 and e.hdl == h then
          return e
        end
      end
      if h ~= 0 then
        return BetterQoL.combo_partners.entry(h)
      end
      return {hdl = 0}
    end
    local out = {entry(player)}
    for k = 1, info.slots do
      local h = picks[k] or 0
      if h == 0 then
        h = BetterQoL.combo_partners.named_default(list, info, k)
      end
      out[#out + 1] = entry(h)
    end
    return out
  end

  function BetterQoL.combo_partners.confirm(screen, player, list, picks, info, mname)
    local s = BetterQoL.combo_partners.text(BetterQoL.combo_partners.TX_ASK, mname)
    local perf = BetterQoL.combo_partners.performers(player, list, picks, info)
    local G = BetterQoL.combo_partners.GW
    BetterQoL.combo_partners.gw_clear()
    local m = math.min(#perf, 4)
    local names = {}
    for i = 1, m do
      local e = perf[i]
      local el = (e.chara ~= nil and e.chara ~= 0 and type(e.element) == "number" and BetterQoL.combo_partners.ELEM_SPR[e.element] ~= nil) and e.element or 0
      local ps = (type(e.pos) == "number" and e.pos >= 0 and e.pos <= 3) and e.pos + 1 or 0
      VRFW.param.set(G.H[i], e.hdl or 0)
      VRFW.param.set(G.I[i], el * 10 + ps)
      names[#names + 1] = string.format("%08X", BetterQoL.combo_partners.U32(e.hdl or 0))
    end
    VRFW.param.set(G.N, m)
    BetterQoL.combo_partners.log("confirm", m, "cards", table.concat(names, " "))
    BetterQoL.combo_partners.help(screen, BetterQoL.combo_partners.TX_HELP_CONFIRM)
    BetterQoL.combo_partners.guide(screen, {{BetterQoL.combo_partners.TX_ACCEPT, BetterQoL.combo_partners.GL_ENTER, BetterQoL.combo_partners.K_ENTER}, {BetterQoL.combo_partners.TX_BACK, BetterQoL.combo_partners.GL_BACK, BetterQoL.combo_partners.K_BACK}})
    local yes = VRFW.question.ask(s, {window = G.WINDOW, object = BetterQoL.combo_partners.U32(perf[1].hdl or 0)})
    if VRFW.param.has(G.N) then
      BetterQoL.combo_partners.log("confirm: general_window did not take the cards (BetterQoL's betterqol_cp_gw hook missing)")
    end
    BetterQoL.combo_partners.gw_clear()
    return yes
  end

  function BetterQoL.combo_partners.preview(screen, picks, slot, hdl)
    if screen.preview == nil then
      return
    end
    local preview = {}
    for k, h in pairs(picks) do
      preview[k] = h
    end
    preview[slot] = hdl or 0
    pcall(screen.preview, preview)
  end

  -- Draws one page.
  function BetterQoL.combo_partners.page(screen, list, picks, slot, info)
    for _, e in ipairs(list) do
      e.taken = false
      if e.hdl ~= 0 then
        for k = 1, info.slots do
          if k ~= slot and picks[k] == e.hdl then
            e.taken = true
          end
        end
      end
    end
    local cur = picks[slot] or 0
    local sel = 0
    for i, e in ipairs(list) do
      if e.hdl == cur then
        sel = i - 1
      end
    end
    local first = math.max(0, math.min(sel, #list - BetterQoL.combo_partners.VIEW))
    BetterQoL.combo_partners.list_show(screen, true, list, first, sel, cur)
    BetterQoL.combo_partners.preview(screen, picks, slot, list[sel + 1].hdl)
    BetterQoL.combo_partners.help(screen, BetterQoL.combo_partners.TX_HELP_PICK)
    BetterQoL.combo_partners.guide(screen, {{BetterQoL.combo_partners.TX_ACCEPT, BetterQoL.combo_partners.GL_ENTER, BetterQoL.combo_partners.K_ENTER}, {BetterQoL.combo_partners.TX_BACK, BetterQoL.combo_partners.GL_BACK, BetterQoL.combo_partners.K_BACK}})
    coroutine.yield()
    while true do
      coroutine.yield()
      if screen.frame ~= nil then
        pcall(screen.frame)
      end
      local moved = false
      if BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_BACK) then
        BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_BACK)
        return nil
      elseif BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_ENTER) or BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_CLICK) then
        if list[sel + 1].taken then
          BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_NG)
        else
          BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_DECIDE)
          return sel
        end
      elseif BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_DOWN) and sel < #list - 1 then
        sel = sel + 1
        if sel >= first + BetterQoL.combo_partners.VIEW then
          first = first + 1
        end
        moved = true
      elseif BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_UP) and sel > 0 then
        sel = sel - 1
        if sel < first then
          first = first - 1
        end
        moved = true
      end
      if moved then
        BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_MOVE)
        BetterQoL.combo_partners.list_show(screen, true, list, first, sel, cur)
        BetterQoL.combo_partners.preview(screen, picks, slot, list[sel + 1].hdl)
      end
    end
  end

  function BetterQoL.combo_partners.open(screen, skill, info)
    local message = screen.message or BetterQoL.combo_partners.message
    local mname = BetterQoL.combo_partners.move_name(skill)
    local player = screen.player
    if player == nil or player == 0 then
      BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_NG)
      BetterQoL.combo_partners.log("open refused: no player known", string.format("skill %08X", skill))
      return
    end
    if info.slots <= 0 then
      BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_NG)
      return
    end
    local list = BetterQoL.combo_partners.candidates(screen, info)
    if list == nil then
      -- Handles being opened without a squad (story field, a scout).
      BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_NG)
      message(BetterQoL.combo_partners.text(BetterQoL.combo_partners.TX_NOTEAM))
      return
    end
    BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_DECIDE)
    screen.begin()
    BetterQoL.combo_partners.picking = true
    local done, err = pcall(function()
      local saved = BetterQoL.combo_partners.get(player, skill)
      local picks = {}
      for k = 1, info.slots do
        -- Handles a named slot with no saved pick.
        picks[k] = saved[k] or 0
        if picks[k] == 0 then
          picks[k] = BetterQoL.combo_partners.named_default(list, info, k)
        end
      end
      local initial = {}
      for k = 1, info.slots do
        initial[k] = picks[k]
      end
      BetterQoL.combo_partners.log("open", string.format("player %08X skill %08X performers %d slots %d named %d team %d", player, skill,
        info.performers, info.slots, #info.named, #list - 1))
      local slot = 1
      while slot >= 1 and slot <= info.slots do
        local i = BetterQoL.combo_partners.page(screen, list, picks, slot, info)
        if i == nil then
          slot = slot - 1
        else
          picks[slot] = list[i + 1].hdl
          slot = slot + 1
        end
      end
      pcall(BetterQoL.combo_partners.list_show, screen, false, {}, 0, 0, 0)
      if slot > info.slots then
        local same = true
        for k = 1, info.slots do
          if (picks[k] or 0) ~= (initial[k] or 0) then
            same = false
          end
        end
        if same then
          BetterQoL.combo_partners.log("unchanged", string.format("skill %08X", skill))
        elseif BetterQoL.combo_partners.confirm(screen, player, list, picks, info, mname) then
          local r = VRFW.host.command(BetterQoL.combo_partners.CMD_SET, player, skill, picks[1] or 0, picks[2] or 0, picks[3] or 0)
          BetterQoL.combo_partners.SE((r == true) and BetterQoL.combo_partners.SE_OK or BetterQoL.combo_partners.SE_NG)
          BetterQoL.combo_partners.log("saved", string.format("player %08X skill %08X -> %08X %08X %08X (%s)", player, skill,
            picks[1] or 0, picks[2] or 0, picks[3] or 0, tostring(r)))
        else
          BetterQoL.combo_partners.log("cancelled at confirm", string.format("skill %08X", skill))
        end
      else
        BetterQoL.combo_partners.log("cancelled", string.format("skill %08X", skill))
      end
    end)
    pcall(BetterQoL.combo_partners.list_show, screen, false, {}, 0, 0, 0)
    pcall(BetterQoL.combo_partners.return_guide, true)
    coroutine.yield()
    BetterQoL.combo_partners.picking = false
    screen.finish()
    if not done then
      BetterQoL.combo_partners.log("picker error", tostring(err))
    end
  end
  -- ===== end of the shared partner picker =====

  BetterQoL.combo_partners.MENU = 1810526795 -- ability_learning_board_menu
  BetterQoL.combo_partners.RING = 2907318182 -- team13_09_effect_grid_focus_ring (the node focus)
  BetterQoL.combo_partners.CURSOR = 4051667112 -- cmn05_01_cursor_ability_learning
  BetterQoL.combo_partners.FN_X = 3091144369
  BetterQoL.combo_partners.PRIO = {BG = 600, LIST = 601, ITEM = 602}
  -- the team dock's parameters the screen's OnInit reads (and clears)
  BetterQoL.combo_partners.P_CHARA = 4161869490
  BetterQoL.combo_partners.P_DOCK_NO = 3357163798
  BetterQoL.combo_partners.P_DOCK_TYPE = 4081600465
  BetterQoL.combo_partners.P_FORMATION = 813466851
  BetterQoL.combo_partners.co = nil

  function BetterQoL.combo_partners.parent()
    if MENU_DEF ~= nil and type(MENU_DEF.GetParentMenuID) == "function" then
      local ok, m = pcall(MENU_DEF.GetParentMenuID)
      if ok and m ~= nil then
        return m
      end
    end
    return 2645952753 -- main_menu
  end

  function BetterQoL.combo_partners.peek(key)
    if not VRFW.param.has(key) then
      return nil
    end
    local v = VRFW.param.get(key)
    return v or nil
  end

  function BetterQoL.combo_partners.seen(h, dock_no, dock_type, formation)
    if type(h) == "number" and h ~= 0 then
      BetterQoL.combo_partners.h = BetterQoL.combo_partners.U32(h)
    end
    if type(dock_no) == "number" then
      BetterQoL.combo_partners.dock_no = dock_no
    end
    if type(dock_type) == "number" then
      BetterQoL.combo_partners.dock_type = dock_type
    end
    if type(formation) == "number" then
      BetterQoL.combo_partners.formation = formation
    end
  end

  -- Returns the focused node.
  function BetterQoL.combo_partners.focused()
    local okf, idx = pcall(funcLuaMenuCommand, 2603265800, BetterQoL.combo_partners.RING)
    if not okf or type(idx) ~= "number" or idx < 0 then
      return nil
    end
    local r = {pcall(funcLuaMenuCommand, 4147077179, idx)}
    if not r[1] then
      return nil
    end
    -- Row fields: layerIdx, posIdx, skillId, selectedSkillId, category, needPoint, canLiberate, isLiberated, isLocked.
    local skill, selected, category, overwrite, secret, editable = r[4], r[5], r[6], r[12], r[13], r[14]
    local s = 0
    if type(selected) == "number" and selected ~= 0 then
      s = selected
    elseif type(overwrite) == "number" and overwrite ~= 0 then
      s = overwrite
    elseif type(skill) == "number" then
      s = skill
    end
    return {idx = idx, skill = BetterQoL.combo_partners.U32(s), category = category, editable = editable == true, secret = secret == true}
  end

  function BetterQoL.combo_partners.focused_combo()
    local f = BetterQoL.combo_partners.focused()
    if f == nil or (f.category ~= 0 and f.category ~= 1) or f.editable or f.secret or f.skill == 0 then
      return nil
    end
    local info = BetterQoL.combo_partners.combo_info(f.skill)
    if info == nil then
      return nil
    end
    return f, info
  end

  function BetterQoL.combo_partners.busy()
    if BetterQoL.combo_partners.co ~= nil then
      return true
    end
    if type(IsRunningManageCoroutine) == "function" then
      for i = 1, 13 do
        local ok, r = pcall(IsRunningManageCoroutine, i)
        if ok and r == true then
          return true
        end
      end
    end
    return false
  end

  function BetterQoL.combo_partners.board_members()
    local dock_no, dock_type = BetterQoL.combo_partners.dock_no, BetterQoL.combo_partners.dock_type
    if type(dock_no) ~= "number" or type(dock_type) ~= "number" then
      return nil
    end
    local out = {formation = BetterQoL.combo_partners.formation}
    local n = dock_type == 2 and 7 or 20
    local okb, flag = pcall(funcLuaCommand, 941426960 --[[CMND_GET_GLOBAL_BIT_FLAG]], 908681340)
    local okx, excluded = pcall(funcLuaCommand, 2668676119, 0)
    for i = 0, n - 1 do
      local ok, got, h = pcall(funcLuaCommand, 1720957768, dock_no, dock_type, i, 0)
      h = (ok and got) and BetterQoL.combo_partners.U32(h) or 0
      if okb and flag and okx and h == BetterQoL.combo_partners.U32(excluded) then
        h = 0
      end
      if h ~= 0 then
        local okp, gotp, posno = pcall(funcLuaCommand, 1720957768, dock_no, dock_type, i, 1)
        out[#out + 1] = {hdl = h, slot = (okp and gotp and type(posno) == "number") and posno or nil, index = i}
      end
    end
    return out
  end

  function BetterQoL.combo_partners.restore()
    pcall(BetterQoL.combo_partners.list_show, BetterQoL.combo_partners.board(), false, {}, 0, 0, 0)
    pcall(funcLuaMenuCommand, 711242136, BetterQoL.combo_partners.CURSOR, 0, true)
    pcall(funcLuaMenuCommand, 1558704558, BetterQoL.combo_partners.MENU, true)
    BetterQoL.combo_partners.last_idx = nil
    if type(UpdateFooterButtonGuide) == "function" then
      pcall(UpdateFooterButtonGuide, BetterQoL.combo_partners.mode or 0)
    end
  end

  function BetterQoL.combo_partners.board()
    return {
      player = BetterQoL.combo_partners.h,
      backdrop = true,
      members = BetterQoL.combo_partners.board_members,
      begin = function()
        funcLuaMenuCommand(1558704558, BetterQoL.combo_partners.MENU, false)
        pcall(funcLuaMenuCommand, 711242136, BetterQoL.combo_partners.CURSOR, 0, false)
      end,
      finish = BetterQoL.combo_partners.restore,
      guide_menu = BetterQoL.combo_partners.parent,
    }
  end

  function BetterQoL.combo_partners.guide_hook(on)
    if on then
      if BetterQoL.combo_partners.cmd_orig ~= nil or type(funcLuaMenuCommand) ~= "function" then
        return
      end
      local orig = funcLuaMenuCommand
      BetterQoL.combo_partners.cmd_orig = orig
      funcLuaMenuCommand = function(cmd, menu, layer, a, b, c, ...)
        if layer == BetterQoL.combo_partners.GUIDE and cmd == BetterQoL.combo_partners.GUIDE_TEXTS and type(a) == "table" and type(b) == "table" and type(c) == "table" then
          local t, g, o = {table.unpack(a)}, {table.unpack(b)}, {table.unpack(c)}
          t[#t + 1], g[#g + 1] = BetterQoL.combo_partners.TX_BTN, BetterQoL.combo_partners.GL_FUNC4
          o[#o + 1] = (#c > 0 and type(c[#c]) == "number") and (c[#c] + 18) or 18
          return orig(cmd, menu, layer, t, g, o, ...)
        elseif layer == BetterQoL.combo_partners.GUIDE and cmd == BetterQoL.combo_partners.GUIDE_KEYS and type(a) == "table" then
          local k = {table.unpack(a)}
          k[#k + 1] = BetterQoL.combo_partners.K_FUNC4
          return orig(cmd, menu, layer, k, b, c, ...)
        end
        return orig(cmd, menu, layer, a, b, c, ...)
      end
    elseif BetterQoL.combo_partners.cmd_orig ~= nil then
      funcLuaMenuCommand = BetterQoL.combo_partners.cmd_orig
      BetterQoL.combo_partners.cmd_orig = nil
    end
  end

  BetterQoL.combo_partners.wrap_global("UpdateFooterButtonGuide", function(prev)
    return function(a1, ...)
      local mode = a1 or 0
      BetterQoL.combo_partners.mode = mode
      local want = false
      if (mode == 0 or mode == 1) and BetterQoL.combo_partners.co == nil then
        local okc, f = pcall(BetterQoL.combo_partners.focused_combo)
        want = okc and f ~= nil
        BetterQoL.combo_partners.guide_idx = (okc and f ~= nil) and f.idx or nil
      end
      BetterQoL.combo_partners.guide_x = want
      if not want then
        return prev(a1, ...)
      end
      BetterQoL.combo_partners.guide_hook(true)
      local r = table.pack(pcall(prev, a1, ...))
      BetterQoL.combo_partners.guide_hook(false)
      if not r[1] then
        error(r[2], 0)
      end
      return table.unpack(r, 2, r.n)
    end
  end)

  BetterQoL.combo_partners.wrap_global("ResetFooterButtonGuide", function(prev)
    return function(...)
      BetterQoL.combo_partners.mode = nil
      BetterQoL.combo_partners.guide_x = false
      return prev(...)
    end
  end)

  -- Polls every frame (Step).
  function BetterQoL.combo_partners.poll()
    if BetterQoL.combo_partners.co ~= nil then
      local ok, err = coroutine.resume(BetterQoL.combo_partners.co)
      if not ok then
        BetterQoL.combo_partners.log("picker error", tostring(err))
        pcall(BetterQoL.combo_partners.restore)
        BetterQoL.combo_partners.co = nil
      elseif coroutine.status(BetterQoL.combo_partners.co) == "dead" then
        BetterQoL.combo_partners.co = nil
      end
      return
    end
    if (BetterQoL.combo_partners.mode ~= 0 and BetterQoL.combo_partners.mode ~= 1) or BetterQoL.combo_partners.busy() then
      return
    end
    local okf, idx = pcall(funcLuaMenuCommand, 2603265800, BetterQoL.combo_partners.RING)
    if not okf or idx == BetterQoL.combo_partners.last_idx then
      return
    end
    BetterQoL.combo_partners.last_idx = idx
    local okc, f = pcall(BetterQoL.combo_partners.focused_combo)
    local want = okc and f ~= nil
    if want ~= (BetterQoL.combo_partners.guide_x == true) and type(UpdateFooterButtonGuide) == "function" then
      pcall(UpdateFooterButtonGuide, BetterQoL.combo_partners.mode)
    end
  end

  BetterQoL.combo_partners.wrap_global("Step", function(prev)
    return function(...)
      local r = table.pack(prev(...))
      pcall(BetterQoL.combo_partners.faces_settle)
      local ok, err = pcall(BetterQoL.combo_partners.poll)
      if not ok then
        BetterQoL.combo_partners.log("poll failed", tostring(err))
      end
      return table.unpack(r, 1, r.n)
    end
  end)

  BetterQoL.combo_partners.wrap_global("OnInit", function(prev)
    return function(...)
      BetterQoL.combo_partners.h, BetterQoL.combo_partners.dock_no, BetterQoL.combo_partners.dock_type, BetterQoL.combo_partners.formation = nil, nil, nil, nil
      BetterQoL.combo_partners.co, BetterQoL.combo_partners.mode, BetterQoL.combo_partners.last_idx, BetterQoL.combo_partners.guide_x = nil, nil, nil, false
      pcall(function()
        BetterQoL.combo_partners.seen(BetterQoL.combo_partners.peek(BetterQoL.combo_partners.P_CHARA), BetterQoL.combo_partners.peek(BetterQoL.combo_partners.P_DOCK_NO), BetterQoL.combo_partners.peek(BetterQoL.combo_partners.P_DOCK_TYPE),
          BetterQoL.combo_partners.peek(BetterQoL.combo_partners.P_FORMATION))
      end)
      return prev(...)
    end
  end)

  BetterQoL.combo_partners.wrap_global("OnChangeTargetChara", function(prev)
    return function(a1, ...)
      pcall(BetterQoL.combo_partners.seen, a1)
      BetterQoL.combo_partners.last_idx = nil
      return prev(a1, ...)
    end
  end)

  -- (charaStHdl, showTeamDockNo, teamDockType, formationId, selectCharaIdx, ...)
  BetterQoL.combo_partners.wrap_global("UpdateAbilityLearningBoardCharaCard", function(prev)
    return function(a1, a2, a3, a4, ...)
      pcall(BetterQoL.combo_partners.seen, a1, a2, a3, a4)
      return prev(a1, a2, a3, a4, ...)
    end
  end)

  BetterQoL.combo_partners.wrap_global("OnFunction", function(prev)
    return function(a1, a2, ...)
      if a1 == BetterQoL.combo_partners.FN_X and BetterQoL.combo_partners.co == nil and (BetterQoL.combo_partners.mode == 0 or BetterQoL.combo_partners.mode == 1) and not BetterQoL.combo_partners.busy() then
        local okc, f, info = pcall(BetterQoL.combo_partners.focused_combo)
        if okc and f ~= nil then
          BetterQoL.combo_partners.co = coroutine.create(function()
            BetterQoL.combo_partners.open(BetterQoL.combo_partners.board(), f.skill, info)
          end)
        end
      end
      return prev(a1, a2, ...)
    end
  end)

  BetterQoL.combo_partners.wrap_global("OnSetupLayer", function(prev)
    return function(a1, a2, ...)
      if BetterQoL.combo_partners.ours(a1) then
        BetterQoL.combo_partners.setup_layer(a1, a2, BetterQoL.combo_partners.PRIO)
        return
      end
      return prev(a1, a2, ...)
    end
  end)

  BetterQoL.combo_partners.wrap_global("OnOpenLayer", function(prev)
    return function(a1, a2, ...)
      if BetterQoL.combo_partners.ours(a1) then
        if BetterQoL.combo_partners.co == nil then
          pcall(funcLuaMenuCommand, 711242136, a1, a2, false)
        end
        return
      end
      return prev(a1, a2, ...)
    end
  end)
end
